return {
    ["VectorUtil"] = {
        ["toNormalId"] = function(p1) --[[ Name: toNormalId, Line 12 ]]
            if p1 == Vector3.new(0, 1, 0) then
                return Enum.NormalId.Top
            elseif p1 == Vector3.new(0, -1, 0) then
                return Enum.NormalId.Bottom
            elseif p1 == Vector3.new(0, 0, 1) then
                return Enum.NormalId.Back
            elseif p1 == Vector3.new(0, 0, -1) then
                return Enum.NormalId.Front
            elseif p1 == Vector3.new(1, 0, 0) then
                return Enum.NormalId.Right
            elseif p1 == Vector3.new(-1, 0, 0) then
                return Enum.NormalId.Left
            else
                return Enum.NormalId.Front
            end
        end,
        ["toVector3"] = function(p2) --[[ Name: toVector3, Line 36 ]]
            local v3 = p2.X
            local v4 = p2.Y
            local v5 = p2.Z
            return Vector3.new(v3, v4, v5)
        end,
        ["toVector3int16"] = function(p6) --[[ Name: toVector3int16, Line 40 ]]
            return Vector3int16.new(p6.X, p6.Y, p6.Z)
        end
    }
}